mapper.update:
UPDATE users
SET failed_attempts = #{failedAttempts},
    locked_until = #{lockedUntil},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE users
SET locked_until = #{lockedUntil},
    updated_at = #{now}
WHERE id = #{id}
  AND locked_until IS NULL
  AND failed_attempts >= #{maxFailedAttempts}

UPDATE users
SET failed_attempts = 0,
    locked_until = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE users
SET totp_secret = #{totpSecret},
    totp_enabled = #{totpEnabled},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE users
SET display_name = #{displayName},
    role = #{role},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE users
SET enabled = #{enabled},
    updated_at = #{updatedAt}
WHERE id = #{id}
